#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

CHECKPOINT_DIR="${CHECKPOINT_DIR:-models/paraphrase-albert-small-v2}"
MODEL_CARD="${MODEL_CARD:-docs/model_card.md}"
CONFUSION_MATRIX="${CONFUSION_MATRIX:-results/confusion_matrix.png}"

# Python with huggingface_hub and this package installed: the repo venv, else python3.
if [[ -x .venv/bin/python ]]; then PY=.venv/bin/python; else PY=python3; fi
if ! "$PY" -c "import huggingface_hub, emotion_classification" >/dev/null 2>&1; then
  printf 'This wizard needs huggingface_hub and the emotion_classification package.\n'
  printf 'Run `pip install -e .` in your environment first (or set up .venv), then re-run.\n'
  exit 1
fi
for f in "$CHECKPOINT_DIR/model.safetensors" "$CHECKPOINT_DIR/config.json" "$MODEL_CARD" "$CONFUSION_MATRIX"; do
  [[ -f "$f" ]] || { printf 'Missing file: %s (run the wizard from the repository root)\n' "$f"; exit 1; }
done

banner "Publish the Checkpoint on the Hugging Face Hub"

# ── 1. Account ─────────────────────────────────────────────────────────────
stage "Hugging Face account"
say "The Checkpoint will live on your own Hugging Face account."
open_url "https://huggingface.co/join"
step "Sign up, or log in if you already have an account."
step "Your username is shown in the URL of your profile page: huggingface.co/<username>."
note "It is not your email address: letters, digits, '-', '_' or '.' only."
HF_USERNAME=""
until [[ "$HF_USERNAME" =~ ^[A-Za-z0-9][A-Za-z0-9_.-]*$ ]]; do
  [[ -z "$HF_USERNAME" ]] || warn "'$HF_USERNAME' is not a valid username (an email address?). Try again."
  ask HF_USERNAME "Your Hugging Face username:" || exit 1
done
write_env HF_USERNAME "$HF_USERNAME"

# ── 2. Access token ────────────────────────────────────────────────────────
stage "Access token"
say "A token with write access lets this script create the repository and upload files."
say "It is only kept in memory for this run: it is not saved in .env."
open_url "https://huggingface.co/settings/tokens"
step "Click 'Create new token'."
step "Choose the 'Write' token type, name it e.g. emotion-classification, and create it."
step "Copy the token (it starts with hf_ and is shown only once)."
ask_secret HF_TOKEN "Paste the token (hidden):"
if HF_NAME=$(HF_TOKEN="$HF_TOKEN" "$PY" -c "from huggingface_hub import HfApi; import os; print(HfApi(token=os.environ['HF_TOKEN']).whoami()['name'])" 2>/dev/null); then
  say "Token accepted for the account: $HF_NAME"
  if [[ "$HF_NAME" != "$HF_USERNAME" ]]; then
    warn "the token belongs to '$HF_NAME', not '$HF_USERNAME': using '$HF_NAME'."
    write_env HF_USERNAME "$HF_NAME"
  fi
else
  warn "Hugging Face rejected this token. Check that you copied all of it, then re-run."
  exit 1
fi

# ── 3. Repository name ─────────────────────────────────────────────────────
stage "Repository name"
say "The model page will be huggingface.co/$HF_USERNAME/<repository name>."
HF_REPO_NAME=""
ask HF_REPO_NAME "Repository name (Enter for paraphrase-albert-small-v2-emotion):"
HF_REPO_NAME="${HF_REPO_NAME:-paraphrase-albert-small-v2-emotion}"
write_env HF_REPO_ID "$HF_USERNAME/$HF_REPO_NAME"

# ── 4. Upload ──────────────────────────────────────────────────────────────
stage "Upload the Checkpoint"
say "Repository: $HF_REPO_ID (public)"
say "Files sent: the weights and tokenizer from $CHECKPOINT_DIR, training_curves.png,"
say "the confusion matrix, and $MODEL_CARD as the model page (README.md)."
note "TensorBoard logs are not sent. Nothing is deleted locally."
confirm "Create the public repository and upload now?" || { warn "Stopped before uploading."; exit 1; }
if ! HF_TOKEN="$HF_TOKEN" HF_REPO_ID="$HF_REPO_ID" CHECKPOINT_DIR="$CHECKPOINT_DIR" \
     MODEL_CARD="$MODEL_CARD" CONFUSION_MATRIX="$CONFUSION_MATRIX" "$PY" - <<'PY'
import os, shutil, tempfile
from pathlib import Path
from huggingface_hub import HfApi

repo_id = os.environ["HF_REPO_ID"]
checkpoint = Path(os.environ["CHECKPOINT_DIR"])
files = ["config.json", "model.safetensors", "special_tokens_map.json", "spiece.model",
         "tokenizer.json", "tokenizer_config.json", "training_curves.png"]

with tempfile.TemporaryDirectory() as staging:
    staging = Path(staging)
    for name in files:
        shutil.copy(checkpoint / name, staging / name)
    shutil.copy(os.environ["CONFUSION_MATRIX"], staging / "confusion_matrix.png")
    card = Path(os.environ["MODEL_CARD"]).read_text().replace("{{REPO_ID}}", repo_id)
    (staging / "README.md").write_text(card)

    api = HfApi(token=os.environ["HF_TOKEN"])
    api.create_repo(repo_id, repo_type="model", private=False, exist_ok=True)
    api.upload_folder(repo_id=repo_id, repo_type="model", folder_path=str(staging),
                      commit_message="Upload fine-tuned Checkpoint and model card")
print("uploaded")
PY
then
  warn "The upload failed (see the error above). Nothing was changed locally; fix the cause and re-run."
  exit 1
fi
say "Uploaded."
open_url "https://huggingface.co/$HF_REPO_ID"
pause "Check the model page renders (card, files, metrics), then press Enter."

# ── 5. Verify ──────────────────────────────────────────────────────────────
stage "Verify the download from the Hub"
say "Loading the model from the Hub into an empty cache, without your token,"
say "the way the API does with EMOTION_CHECKPOINT=$HF_REPO_ID."
if HF_HOME="$(mktemp -d)" HF_REPO_ID="$HF_REPO_ID" env -u HF_TOKEN "$PY" - <<'PY'
import os
from emotion_classification.config import id2label
from emotion_classification.inference import BertClassifierInference

inference = BertClassifierInference(os.environ["HF_REPO_ID"])
text = "i am so happy to see you again today"
prediction = id2label[inference.predict(text)]
print(f"{text!r} -> {prediction}")
assert prediction == "joy", f"expected joy, got {prediction}"
PY
then
  say "The Checkpoint loads from the Hub and predicts correctly."
  say "Next: tell Claude it worked, so the weights can be removed from the working tree."
else
  warn "Loading from the Hub failed. Do NOT delete the local weights; see the error above."
  exit 1
fi

finish
}

run_wizard "$@"; exit
